<template>
  <div class="manager-page"><div class="page-heading"><div><div class="eyebrow">COMMUNITY</div><h1>评论管理</h1><p>维护社区讨论秩序，处理不当评论。</p></div></div><div class="card table-card"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="搜索评论或用户" style="width:280px"><template #prefix><el-icon><Search /></el-icon></template></el-input><div class="grow"></div><span class="text-muted">共 {{ filtered.length }} 条评论</span></div><el-table :data="paged" stripe><el-table-column label="评论用户" width="150"><template #default="{row}"><div class="user-cell"><img :src="row.avatar || '/images/avatars/student.svg'"/><span>{{row.userName}}</span></div></template></el-table-column><el-table-column prop="content" label="评论内容" min-width="350"/><el-table-column prop="articleTitle" label="所属文章" min-width="180"/><el-table-column label="时间" width="160"><template #default="{row}">{{date(row.createTime)}}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button text type="danger" @click="del(row.id)">删除</el-button></template></el-table-column></el-table><div class="pagination-wrap"><el-pagination background layout="prev,pager,next" :total="filtered.length" :page-size="pageSize" v-model:current-page="pageNum"/></div></div></div>
</template>
<script setup>
import {ref,computed,onMounted} from 'vue';import request from '@/utils/request';import {ElMessage,ElMessageBox} from 'element-plus'
const data=ref([]),keyword=ref(''),pageNum=ref(1),pageSize=8;const date=v=>v?String(v).replace('T',' ').slice(0,16):'';const filtered=computed(()=>data.value.filter(x=>!keyword.value||(x.content+x.userName+(x.articleTitle||'')).includes(keyword.value)));const paged=computed(()=>filtered.value.slice((pageNum.value-1)*pageSize,pageNum.value*pageSize));const load=()=>request.get('/article/comments/all').then(res=>{if(res.code==='200')data.value=res.data||[]});const del=id=>ElMessageBox.confirm('确认删除该评论？','删除确认').then(()=>request.delete('/article/comment/'+id).then(res=>{if(res.code==='200'){ElMessage.success('已删除');load()}else ElMessage.error(res.msg)}));onMounted(load)
</script>
<style scoped>.user-cell{display:flex;align-items:center;gap:8px}.user-cell img{width:30px;height:30px;border-radius:50%;object-fit:cover}</style>
